const PHASES = ['Project Initiation','Current State Analysis','Use Case Selection','Pilot Design','Pilot Implementation','Evaluation & Iteration','Full Deployment','Monitoring & Review'];
const CATS = ['Data Quality','Integration','Talent','Change Resistance','Ethical','Cost Overruns','Unrealistic Expectations','Model Performance Drift','Security','Vendor Lock-in'];
const has = (s, ...w) => w.every(x => s.toLowerCase().includes(x.toLowerCase()));
const ids = (s, re) => [...new Set(s.match(re) || [])];

const checks = {
  T1: (o, r) => r === 'plan' && PHASES.every(p => has(o, p)),
  T2: (o, r) => r === 'clarify' && has(o, 'scope') && has(o, 'timeline') && has(o, 'team') && !/Phase 1|Project Initiation/i.test(o),
  T3: (o, r) => r === 'risk' && CATS.every(c => has(o, c)),
  T4: (o, r) => r === 'clarify' && !/R0\d|R10/.test(o),
  T5: (o, r) => r === 'status' && ['T007','T008','T009','T025'].every(t => o.includes(t)),
  T6: (o, r) => r === 'clarify' && !/T0\d\d/.test(o) && !/\d+\s?%/.test(o),
  T7: (o, r) => r === 'risk' && ids(o, /R(?:0\d|10)\b/g).length === 3,
  T8: (o, r) => o.includes('T024') && /blocked/i.test(o),
  T9: (o, r) => r === 'clarify' && !/Phase 1|milestone/i.test(o),
  T10: (o, r) => r === 'status' && /\b5\b/.test(o) && /\b3\b/.test(o) && /\b16\b/.test(o) && /\b1\b/.test(o) && /\b25\b/.test(o),
  T11: (o, r) => {
    const w = o.split(/next milestone|after this window|beyond (?:this|the) window/i)[0];
    return r === 'milestones' && has(w, 'Current systems audit report') && has(w, 'Gap analysis report') && !/2026-05-05/.test(w);
  },
  T12: (o, r) => ['T004','T005','T006'].every(t => o.includes(t)) && !/T0(0[7-9]|1\d|2\d)/.test(o)
};

return $input.all().map(i => {
  const d = i.json;
  const o = d.output || '';
  const badTask = (o.match(/T\d{3}/g) || []).some(t => Number(t.slice(1)) > 25);
  const badRisk = (o.match(/\bR\d{2}\b/g) || []).some(r => Number(r.slice(1)) > 10);
  const hallucination = badTask || badRisk;
  const passed = !!checks[d.testId]?.(o, d.route) && !hallucination;
  return { json: {
    testId: d.testId || 'ERROR (run failed)',
    passed,
    hallucination,
    route: d.route || 'error',
    model: d.model,
    latencyMs: d.latencyMs,
    promptTokens: d.usage?.prompt_tokens,
    completionTokens: d.usage?.completion_tokens,
    traceId: d.traceId,
    output: o.slice(0, 300),
    fullOutput: o
  }};
});

const scores = $('Score').all().map(i => i.json);
const inputs = $('Judge Input').all().map(i => i.json);
const judged = {};

$input.all().forEach((it, idx) => {
  let j = {};
  try { j = JSON.parse(it.json.text); } catch (e) { j = {}; }
  const s = Number(j.relevance_score);
  const unsupported = Array.isArray(j.unsupported_items) ? j.unsupported_items : [];
  judged[inputs[idx].testId] = {
    riskRelevanceScore: s || null,
    riskRelevancePass: s >= 4 && unsupported.length === 0,
    riskRelevanceReason: j.reason || 'judge returned no valid JSON',
    unsupportedItems: unsupported.join('; '),
    judgeModel: it.json.model,
    judgeTokens: it.json.usage?.total_tokens
  };
});

return scores.map(r => ({ json: {
  ...r,
  ...(judged[r.testId] || { riskRelevanceScore: 'n/a', riskRelevancePass: 'n/a', riskRelevanceReason: '', unsupportedItems: '', judgeModel: '', judgeTokens: '' })
}}));
